package com.gameaggregator.releaseservice.domain;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity @Table(name="release_decisions") public class ReleaseDecision{@Id public UUID id=UUID.randomUUID();@Column(nullable=false)public UUID releaseId;@Column(nullable=false)public UUID actorId;@Column(nullable=false)public String decision;public String comment;@Column(nullable=false)public Instant createdAt=Instant.now();protected ReleaseDecision(){}public ReleaseDecision(UUID r,UUID a,String d,String c){releaseId=r;actorId=a;decision=d;comment=c;}}